17	package org.keycloak.crypto;
18	
19	import java.security.Key;
20	import java.security.cert.X509Certificate;
21	import java.util.ArrayList;
22	import java.util.List;
23	import javax.crypto.SecretKey;
24	
25	import static org.keycloak.common.crypto.CryptoConstants.EC_KEY_SECP256R1;
26	import static org.keycloak.common.crypto.CryptoConstants.EC_KEY_SECP384R1;
27	import static org.keycloak.common.crypto.CryptoConstants.EC_KEY_SECP521R1;
28	
29	public class KeyWrapper {
30	
31	    private String providerId;
32	    private long providerPriority;
33	    private String kid;
34	    private String algorithm;
35	    private String type;
36	    private KeyUse use;
37	    private KeyStatus status;
38	    private SecretKey secretKey;
39	    private Key publicKey;
40	    private Key privateKey;
41	    private X509Certificate certificate;
42	    private List<X509Certificate> certificateChain;
43	    private boolean isDefaultClientCertificate;
44	    private String curve;
45	
46	    public String getProviderId() {
47	        return providerId;
48	    }
49	
50	    public void setProviderId(String providerId) {
51	        this.providerId = providerId;
52	    }
53	
54	    public long getProviderPriority() {
55	        return providerPriority;
56	    }
57	
58	    public void setProviderPriority(long providerPriority) {
59	        this.providerPriority = providerPriority;
60	    }
61	
62	    public String getKid() {
63	        return kid;
64	    }
65	
66	    public void setKid(String kid) {
67	        this.kid = kid;
68	    }
69	
70	    /**
71	     * <p>Returns the value of the optional {@code alg} claim.
72	     *
73	     * @return the algorithm value
74	     */
75	    public String getAlgorithm() {
76	        return algorithm;
77	    }
78	
79	    /**
80	     * <p>Returns the value of the optional {@code alg} claim. If not defined, a default is
81	     * inferred for some algorithms.
82	     *
83	     * <p>For keys of type {@link KeyType#RSA}, the default algorithm is {@link Algorithm#RS256} as this is the default
84	     * algorithm recommended by OIDC specs.
85	     *
86	     * <p>For keys of type {@link KeyType#EC}, {@link Algorithm#ES256}, {@link Algorithm#ES384}, or {@link Algorithm#ES512}
87	     * is returned based on the curve
88	     *
89	     * <p>For keys of type {@link KeyType#OKP}, {@link Algorithm#EdDSA} as that is the only value supported for that key type
90	     *
91	     * @return the algorithm set or a default based on the key type.
92	     */
93	    public String getAlgorithmOrDefault() {
94	        if (algorithm == null && type != null) {
95	            switch (type) {
96	                case KeyType.EC:
97	                    if (curve != null) {
98	                        switch (curve) {
99	                            case "P-256":
100	                            case EC_KEY_SECP256R1:
101	                                return Algorithm.ES256;
102	                            case "P-384":
103	                            case EC_KEY_SECP384R1:
104	                                return Algorithm.ES384;
105	                            case "P-512":
106	                            case "P-521":
107	                            case EC_KEY_SECP521R1:
108	                                return Algorithm.ES512;
109	                        }
110	                    }
111	                case KeyType.RSA:
112	                    return Algorithm.RS256;
113	                case KeyType.OKP:
114	                    return Algorithm.EdDSA;
115	            }
116	        }
117	        return algorithm;
118	    }
119	
120	    public void setAlgorithm(String algorithm) {
121	        this.algorithm = algorithm;
122	    }
123	
124	    public String getType() {
125	        return type;
126	    }
127	
128	    public void setType(String type) {
129	        this.type = type;
130	    }
131	
132	    public KeyUse getUse() {
133	        return use;
134	    }
135	
136	    public void setUse(KeyUse use) {
137	        this.use = use;
138	    }
139	
140	    public KeyStatus getStatus() {
141	        return status;
142	    }
143	
144	    public void setStatus(KeyStatus status) {
145	        this.status = status;
146	    }
147	
148	    public SecretKey getSecretKey() {
149	        return secretKey;
150	    }
151	
152	    public void setSecretKey(SecretKey secretKey) {
153	        this.secretKey = secretKey;
154	    }
155	
156	    public Key getPrivateKey() {
157	        return privateKey;
158	    }
159	
160	    public void setPrivateKey(Key privateKey) {
161	        this.privateKey = privateKey;
162	    }
163	
164	    public Key getPublicKey() {
165	        return publicKey;
166	    }
167	
168	    public void setPublicKey(Key publicKey) {
169	        this.publicKey = publicKey;
170	    }
171	
172	    public X509Certificate getCertificate() {
173	        return certificate;
174	    }
175	
176	    public void setCertificate(X509Certificate certificate) {
177	        this.certificate = certificate;
178	    }
179	
180	    public List<X509Certificate> getCertificateChain() {
181	        return certificateChain;
182	    }
183	
184	    public void setCertificateChain(List<X509Certificate> certificateChain) {
185	        this.certificateChain = certificateChain;
186	    }
187	
188	    public boolean isDefaultClientCertificate() {
189	        return isDefaultClientCertificate;
190	    }
191	
192	    public void setIsDefaultClientCertificate(boolean isDefaultClientCertificate) {
193	        this.isDefaultClientCertificate = isDefaultClientCertificate;
194	    }
195	
196	    public void setCurve(String curve) {
197	        this.curve = curve;
198	    }
199	
200	    public String getCurve() {
201	        return curve;
202	    }
203	
204	    public KeyWrapper cloneKey() {
205	        KeyWrapper key = new KeyWrapper();
206	        key.providerId = this.providerId;
207	        key.providerPriority = this.providerPriority;
208	        key.kid = this.kid;
209	        key.algorithm = this.algorithm;
210	        key.type = this.type;
211	        key.use = this.use;
212	        key.status = this.status;
213	        key.secretKey = this.secretKey;
214	        key.publicKey = this.publicKey;
215	        key.privateKey = this.privateKey;
216	        key.certificate = this.certificate;
217	        key.curve = this.curve;
218	        if (this.certificateChain != null) {
219	            key.certificateChain = new ArrayList<>(this.certificateChain);
220	        }
221	        key.isDefaultClientCertificate = this.isDefaultClientCertificate;
222	        return key;
223	    }
224	}
