18	package org.keycloak.common.util;
19	
20	import java.math.BigInteger;
21	import java.security.GeneralSecurityException;
22	import java.security.InvalidKeyException;
23	import java.security.KeyPair;
24	import java.security.PrivateKey;
25	import java.security.SignatureException;
26	import java.security.cert.X509Certificate;
27	import java.util.Date;
28	
29	import org.keycloak.common.crypto.CryptoIntegration;
30	
31	import org.jboss.logging.Logger;
32	
33	/**
34	 * The Class CertificateUtils provides utility functions for generation of V1 and V3 {@link java.security.cert.X509Certificate}
35	 *
36	 */
37	public class CertificateUtils {
38	
39	    private static final Logger logger = Logger.getLogger(CertificateUtils.class);
40	
41	    /**
42	     * RFC 5280 {@code ub-common-name} upper bound. BouncyCastle 1.85+ enforces this limit
43	     * when building X.500 names, so CN values are truncated before they reach the provider.
44	     */
45	    private static final int MAX_CN_LENGTH = 64;
46	
47	    /**
48	     * Generates version 3 {@link java.security.cert.X509Certificate}.
49	     *
50	     * @param keyPair the key pair
51	     * @param caPrivateKey the CA private key
52	     * @param caCert the CA certificate
53	     * @param subject the subject name
54	     *
55	     * @return the x509 certificate
56	     *
57	     * @throws Exception the exception
58	     */
59	    public static X509Certificate generateV3Certificate(KeyPair keyPair, PrivateKey caPrivateKey,
60	            X509Certificate caCert, String subject) throws Exception {
61	        return CryptoIntegration.getProvider().getCertificateUtils().generateV3Certificate(keyPair, caPrivateKey,
62	                caCert, truncateCN(subject));
63	    }
64	
65	    /**
66	     * Generate version 1 self signed {@link java.security.cert.X509Certificate}.
67	     *
68	     * @param caKeyPair the CA key pair
69	     * @param subject the subject name
70	     *
71	     * @return the x509 certificate
72	     *
73	     * @throws Exception the exception
74	     */
75	    public static X509Certificate generateV1SelfSignedCertificate(KeyPair caKeyPair, String subject) {
76	        return CryptoIntegration.getProvider().getCertificateUtils().generateV1SelfSignedCertificate(caKeyPair, truncateCN(subject));
77	    }
78	
79	    public static X509Certificate generateV1SelfSignedCertificate(KeyPair caKeyPair, String subject, BigInteger serialNumber) {
80	        return CryptoIntegration.getProvider().getCertificateUtils().generateV1SelfSignedCertificate(caKeyPair, truncateCN(subject), serialNumber);
81	    }
82	
83	    public static X509Certificate generateV1SelfSignedCertificate(KeyPair caKeyPair, String subject, BigInteger serialNumber, Date validityEndDate) {
84	        return CryptoIntegration.getProvider().getCertificateUtils().generateV1SelfSignedCertificate(caKeyPair, truncateCN(subject), serialNumber, validityEndDate);
85	    }
86	
87	    /**
88	     * Checks whether the certificate is self signed, meaning it is self issued with matching subject and
89	     * issuer names and its signature verifies with its own public key.
90	     *
91	     * @param certificate the certificate to check
92	     * @return true if the certificate is self issued and signed by its own key
93	     * @throws GeneralSecurityException if the signature cannot be verified at all
94	     */
95	    public static boolean isSelfSigned(X509Certificate certificate) throws GeneralSecurityException {
96	        if (!certificate.getSubjectX500Principal().equals(certificate.getIssuerX500Principal())) {
97	            return false;
98	        }
99	        try {
100	            certificate.verify(certificate.getPublicKey());
101	            return true;
102	        } catch (SignatureException | InvalidKeyException e) {
103	            return false;
104	        }
105	    }
106	
107	    private static String truncateCN(String cn) {
108	        if (cn != null && cn.length() > MAX_CN_LENGTH) {
109	            logger.warnf("Certificate CN value exceeds %d characters and will be truncated: '%s'", MAX_CN_LENGTH, cn);
110	            return cn.substring(0, MAX_CN_LENGTH);
111	        }
112	        return cn;
113	    }
114	
115	}
