18	package org.keycloak;
19	
20	import java.nio.charset.StandardCharsets;
21	import java.security.PublicKey;
22	import java.util.Arrays;
23	import java.util.Iterator;
24	import java.util.LinkedList;
25	import java.util.List;
26	import java.util.logging.Level;
27	import java.util.logging.Logger;
28	import javax.crypto.SecretKey;
29	
30	import org.keycloak.common.VerificationException;
31	import org.keycloak.crypto.SignatureVerifierContext;
32	import org.keycloak.exceptions.TokenNotActiveException;
33	import org.keycloak.exceptions.TokenSignatureInvalidException;
34	import org.keycloak.jose.jws.AlgorithmType;
35	import org.keycloak.jose.jws.JWSHeader;
36	import org.keycloak.jose.jws.JWSInput;
37	import org.keycloak.jose.jws.JWSInputException;
38	import org.keycloak.jose.jws.crypto.ECDSAProvider;
39	import org.keycloak.jose.jws.crypto.HMACProvider;
40	import org.keycloak.jose.jws.crypto.RSAProvider;
41	import org.keycloak.representations.JsonWebToken;
42	import org.keycloak.util.TokenUtil;
43	
44	/**
45	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
46	 * @version $Revision: 1 $
47	 */
48	public class TokenVerifier<T extends JsonWebToken> {
49	
50	    private static final Logger LOG = Logger.getLogger(TokenVerifier.class.getName());
51	
52	    /**
53	     * Functional interface of checks that verify some part of a JWT.
54	     * @param <T> Type of the token handled by this predicate.
55	     */
56	    @FunctionalInterface
57	    public interface Predicate<T extends JsonWebToken> {
58	        /**
59	         * Performs a single check on the given token verifier.
60	         * @param t Token, guaranteed to be non-null.
61	         * @return
62	         * @throws VerificationException
63	         */
64	        boolean test(T t) throws VerificationException;
65	    }
66	
67	    public static final Predicate<JsonWebToken> SUBJECT_EXISTS_CHECK = new Predicate<JsonWebToken>() {
68	        @Override
69	        public boolean test(JsonWebToken t) throws VerificationException {
70	            String subject = t.getSubject();
71	            if (subject == null) {
72	                throw new VerificationException("Subject missing in token");
73	            }
74	
75	            return true;
76	        }
77	    };
78	
79	    /**
80	     * Check for token being neither expired nor used before it gets valid.
81	     * @see JsonWebToken#isActive()
82	     */
83	    public static final Predicate<JsonWebToken> IS_ACTIVE = new Predicate<JsonWebToken>() {
84	        @Override
85	        public boolean test(JsonWebToken t) throws VerificationException {
86	            if (! t.isActive()) {
87	                throw new TokenNotActiveException(t, "Token is not active");
88	            }
89	
90	            return true;
91	        }
92	    };
93	
94	    public static class RealmUrlCheck implements Predicate<JsonWebToken> {
95	
96	        private static final RealmUrlCheck NULL_INSTANCE = new RealmUrlCheck(null);
97	
98	        private final String realmUrl;
99	
100	        public RealmUrlCheck(String realmUrl) {
101	            this.realmUrl = realmUrl;
102	        }
103	
104	        @Override
105	        public boolean test(JsonWebToken t) throws VerificationException {
106	            if (this.realmUrl == null) {
107	                throw new VerificationException("Realm URL not set");
108	            }
109	
110	            if (! this.realmUrl.equals(t.getIssuer())) {
111	                throw new VerificationException("Invalid token issuer. Expected '" + this.realmUrl + "'");
112	            }
113	
114	            return true;
115	        }
116	    }
117	
118	    public static class TokenTypeCheck implements Predicate<JsonWebToken> {
119	
120	        private static final TokenTypeCheck INSTANCE_DEFAULT_TOKEN_TYPE = new TokenTypeCheck(Arrays.asList(TokenUtil.TOKEN_TYPE_BEARER));
121	
122	        private final List<String> tokenTypes;
123	
124	        public TokenTypeCheck(List<String> tokenTypes) {
125	            this.tokenTypes = tokenTypes;
126	        }
127	
128	        @Override
129	        public boolean test(JsonWebToken t) throws VerificationException {
130	            for (String tokenType : tokenTypes) {
131	                if (tokenType.equalsIgnoreCase(t.getType())) return true;
132	            }
133	            throw new VerificationException("Token type is incorrect. Expected '" + tokenTypes + "' but was '" + t.getType() + "'");
134	        }
135	    }
136	
137	
138	    public static class AudienceCheck implements Predicate<JsonWebToken> {
139	
140	        private final String expectedAudience;
141	
142	        public AudienceCheck(String expectedAudience) {
143	            this.expectedAudience = expectedAudience;
144	        }
145	
146	        @Override
147	        public boolean test(JsonWebToken t) throws VerificationException {
148	            if (expectedAudience == null) {
149	                throw new VerificationException("Missing expectedAudience");
150	            }
151	
152	            String[] audience = t.getAudience();
153	            if (audience == null) {
154	                throw new VerificationException("No audience in the token");
155	            }
156	
157	            if (t.hasAudience(expectedAudience)) {
158	                return true;
159	            }
160	
161	            throw new VerificationException("Expected audience not available in the token");
162	        }
163	    }
164	
165	
166	    public static class IssuedForCheck implements Predicate<JsonWebToken> {
167	
168	        private final String expectedIssuedFor;
169	
170	        public IssuedForCheck(String expectedIssuedFor) {
171	            this.expectedIssuedFor = expectedIssuedFor;
172	        }
173	
174	        @Override
175	        public boolean test(JsonWebToken jsonWebToken) throws VerificationException {
176	            if (expectedIssuedFor == null) {
177	                throw new VerificationException("Missing expectedIssuedFor");
178	            }
179	
180	            if (expectedIssuedFor.equals(jsonWebToken.getIssuedFor())) {
181	                return true;
182	            }
183	
184	            throw new VerificationException("Expected issuedFor doesn't match");
185	        }
186	    }
187	
188	
189	    private String tokenString;
190	    private Class<? extends T> clazz;
191	    private PublicKey publicKey;
192	    private SecretKey secretKey;
193	    private String realmUrl;
194	    private List<String> expectedTokenType = Arrays.asList(TokenUtil.TOKEN_TYPE_BEARER, TokenUtil.TOKEN_TYPE_DPOP);
195	    private boolean checkTokenType = true;
196	    private boolean checkRealmUrl = true;
197	    private final LinkedList<Predicate<? super T>> checks = new LinkedList<>();
198	
199	    private JWSInput jws;
200	    private T token;
201	
202	    private SignatureVerifierContext verifier = null;
203	
204	    public TokenVerifier<T> verifierContext(SignatureVerifierContext verifier) {
205	        this.verifier = verifier;
206	        return this;
207	    }
208	
209	    protected TokenVerifier(String tokenString, Class<T> clazz) {
210	        this.tokenString = tokenString;
211	        this.clazz = clazz;
212	    }
213	
214	    protected TokenVerifier(T token) {
215	        this.token = token;
216	    }
217	
218	    /**
219	     * Creates an instance of {@code TokenVerifier} from the given string on a JWT of the given class.
220	     * The token verifier has no checks defined. Note that the checks are only tested when
221	     * {@link #verify()} method is invoked.
222	     * @param <T> Type of the token
223	     * @param tokenString String representation of JWT
224	     * @param clazz Class of the token
225	     * @return
226	     */
227	    public static <T extends JsonWebToken> TokenVerifier<T> create(String tokenString, Class<T> clazz) {
228	        return new TokenVerifier<>(tokenString, clazz);
229	    }
230	
231	    /**
232	     * Creates an instance of {@code TokenVerifier} for the given token.
233	     * The token verifier has no checks defined. Note that the checks are only tested when
234	     * {@link #verify()} method is invoked.
235	     * <p>
236	     * <b>NOTE:</b> The returned token verifier cannot verify token signature since
237	     * that is not part of the {@link JsonWebToken} object.
238	     * @return
239	     */
240	    public static <T extends JsonWebToken> TokenVerifier<T> createWithoutSignature(T token) {
241	        return new TokenVerifier<>(token);
242	    }
243	
244	    /**
245	     * Adds default checks to the token verification:
246	     * <ul>
247	     * <li>Realm URL (JWT issuer field: {@code iss}) has to be defined and match realm set via {@link #realmUrl(java.lang.String)} method</li>
248	     * <li>Subject (JWT subject field: {@code sub}) has to be defined</li>
249	     * <li>Token type (JWT type field: {@code typ}) has to be {@code Bearer}. The type can be set via {@link #tokenType(List)} method</li>
250	     * <li>Token has to be active, ie. both not expired and not used before its validity (JWT issuer fields: {@code exp} and {@code nbf})</li>
251	     * </ul>
252	     * @return This token verifier.
253	     */
254	    public TokenVerifier<T> withDefaultChecks()  {
255	        return withChecks(
256	          RealmUrlCheck.NULL_INSTANCE,
257	          TokenTypeCheck.INSTANCE_DEFAULT_TOKEN_TYPE,
258	          IS_ACTIVE
259	        );
260	    }
261	
262	    private void removeCheck(Class<? extends Predicate<?>> checkClass) {
263	        for (Iterator<Predicate<? super T>> it = checks.iterator(); it.hasNext();) {
264	            if (it.next().getClass() == checkClass) {
265	                it.remove();
266	            }
267	        }
268	    }
269	
270	    private void removeCheck(Predicate<? super T> check) {
271	        checks.remove(check);
272	    }
273	
274	    @SuppressWarnings("unchecked")
275	    private <P extends Predicate<? super T>> TokenVerifier<T> replaceCheck(Class<? extends Predicate<?>> checkClass, boolean active, P... predicate) {
276	        removeCheck(checkClass);
277	        if (active) {
278	            checks.addAll(Arrays.asList(predicate));
279	        }
280	        return this;
281	    }
282	
283	    @SuppressWarnings("unchecked")
284	    private <P extends Predicate<? super T>> TokenVerifier<T> replaceCheck(Predicate<? super T> check, boolean active, P... predicate) {
285	        removeCheck(check);
286	        if (active) {
287	            checks.addAll(Arrays.asList(predicate));
288	        }
289	        return this;
290	    }
291	
292	    /**
293	     * Will test the given checks in {@link #verify()} method in addition to already set checks.
294	     * @param checks
295	     * @return
296	     */
297	    @SafeVarargs
298	    public final TokenVerifier<T> withChecks(Predicate<? super T>... checks) {
299	        if (checks != null) {
300	            this.checks.addAll(Arrays.asList(checks));
301	        }
302	        return this;
303	    }
304	
305	    /**
306	     * Sets the key for verification of RSA-based signature.
307	     * @param publicKey
308	     * @return
309	     */
310	    public TokenVerifier<T> publicKey(PublicKey publicKey) {
311	        this.publicKey = publicKey;
312	        return this;
313	    }
314	
315	    /**
316	     * Sets the key for verification of HMAC-based signature.
317	     * @param secretKey
318	     * @return
319	     */
320	    public TokenVerifier<T> secretKey(SecretKey secretKey) {
321	        this.secretKey = secretKey;
322	        return this;
323	    }
324	
325	    /**
326	     * @deprecated This method is here only for backward compatibility with previous version of {@code TokenVerifier}.
327	     * @return This token verifier
328	     */
329	    public TokenVerifier<T> realmUrl(String realmUrl) {
330	        this.realmUrl = realmUrl;
331	        return replaceCheck(RealmUrlCheck.class, checkRealmUrl, new RealmUrlCheck(realmUrl));
332	    }
333	
334	    /**
335	     * @deprecated This method is here only for backward compatibility with previous version of {@code TokenVerifier}.
336	     * @return This token verifier
337	     */
338	    public TokenVerifier<T> checkTokenType(boolean checkTokenType) {
339	        this.checkTokenType = checkTokenType;
340	        return replaceCheck(TokenTypeCheck.class, this.checkTokenType, new TokenTypeCheck(expectedTokenType));
341	    }
342	
343	    /**
344	     *
345	     * @return This token verifier
346	     */
347	    public TokenVerifier<T> tokenType(List<String> tokenTypes) {
348	        this.expectedTokenType = tokenTypes;
349	        return replaceCheck(TokenTypeCheck.class, this.checkTokenType, new TokenTypeCheck(expectedTokenType));
350	    }
