369	    /**
370	     * Add check for verifying that token contains the expectedAudience
371	     *
372	     * @param expectedAudiences Audiences, which needs to be in the target token. Can be <code>null</code>.
373	     * @return This token verifier
374	     */
375	    public TokenVerifier<T> audience(String... expectedAudiences) {
376	        if (expectedAudiences == null || expectedAudiences.length == 0) {
377	            return this.replaceCheck(AudienceCheck.class, true, new AudienceCheck(null));
378	        }
379	        AudienceCheck[] audienceChecks = new AudienceCheck[expectedAudiences.length];
380	        for (int i = 0; i < expectedAudiences.length; ++i) {
381	            audienceChecks[i] = new AudienceCheck(expectedAudiences[i]);
382	        }
383	        return this.replaceCheck(AudienceCheck.class, true, audienceChecks);
384	    }
