395	
396	    public TokenVerifier<T> parse() throws VerificationException {
397	        if (jws == null) {
398	            if (tokenString == null) {
399	                throw new VerificationException("Token not set");
400	            }
401	
402	            try {
403	                jws = new JWSInput(tokenString);
404	            } catch (JWSInputException e) {
405	                throw new VerificationException("Failed to parse JWT", e);
406	            }
407	
408	
409	            try {
410	                token = jws.readJsonContent(clazz);
411	            } catch (JWSInputException e) {
412	                throw new VerificationException("Failed to read access token from JWT", e);
413	            }
414	        }
415	        return this;
416	    }
417	
418	    public T getToken() throws VerificationException {
419	        if (token == null) {
420	            parse();
421	        }
422	        return token;
423	    }
424	
425	    public JWSHeader getHeader() throws VerificationException {
426	        parse();
427	        return jws.getHeader();
428	    }
429	
430	    public void verifySignature() throws VerificationException {
431	        if (this.verifier != null) {
432	            try {
433	                if (!verifier.verify(jws.getEncodedSignatureInput().getBytes(StandardCharsets.UTF_8), jws.getSignature())) {
434	                    throw new TokenSignatureInvalidException(token, "Invalid token signature");
435	                }
436	            } catch (Exception e) {
437	                throw new VerificationException(e);
438	            }
439	        } else {
440	            AlgorithmType algorithmType = getHeader().getAlgorithm().getType();
441	            if (null == algorithmType) {
442	                throw new VerificationException("Unknown or unsupported token algorithm");
443	            }
444	            switch (algorithmType) {
445	                case RSA:
446	                    if (publicKey == null) {
447	                        throw new VerificationException("Public key not set");
448	                    }
449	                    if (!RSAProvider.verify(jws, publicKey)) {
450	                        throw new TokenSignatureInvalidException(token, "Invalid token signature");
451	                    }
452	                    break;
453	                case ECDSA:
454	                    if (publicKey == null) {
455	                        throw new VerificationException("Public key not set");
456	                    }
457	                    if (!ECDSAProvider.verify(jws, publicKey)) {
458	                        throw new TokenSignatureInvalidException(token, "Invalid token signature");
459	                    }
460	                    break;
461	                case HMAC:
462	                    if (secretKey == null) {
463	                        throw new VerificationException("Secret key not set");
464	                    }
465	                    if (!HMACProvider.verify(jws, secretKey)) {
466	                        throw new TokenSignatureInvalidException(token, "Invalid token signature");
467	                    }
468	                    break;
469	                default:
470	                    throw new VerificationException("Unknown or unsupported token algorithm");
471	            }
472	        }
473	    }
474	
475	    public TokenVerifier<T> verify() throws VerificationException {
476	        if (getToken() == null) {
477	            parse();
478	        }
479	        if (jws != null) {
480	            verifySignature();
481	        }
482	
483	        for (Predicate<? super T> check : checks) {
484	            if (! check.test(getToken())) {
485	                throw new VerificationException("JWT check failed for check " + check);
486	            }
487	        }
488	
489	        return this;
490	    }
491	
492	    /**
493	     * Creates an optional predicate from a predicate that will proceed with check but always pass.
494	     * @param <T>
495	     * @param mandatoryPredicate
496	     * @return
497	     */
498	    public static <T extends JsonWebToken> Predicate<T> optional(final Predicate<T> mandatoryPredicate) {
499	        return new Predicate<T>() {
500	            @Override
501	            public boolean test(T t) throws VerificationException {
502	                try {
503	                    if (! mandatoryPredicate.test(t)) {
504	                        LOG.finer("[optional] predicate failed: " + mandatoryPredicate);
505	                    }
506	
507	                    return true;
508	                } catch (VerificationException ex) {
509	                    LOG.log(Level.FINER, "[optional] predicate " + mandatoryPredicate + " failed.", ex);
510	                    return true;
511	                }
512	            }
513	        };
514	    }
515	
516	    /**
517	     * Creates a predicate that will proceed with checks of the given predicates
518	     * and will pass if and only if at least one of the given predicates passes.
519	     * @param <T>
520	     * @param predicates
521	     * @return
522	     */
523	    @SafeVarargs
524	    public static <T extends JsonWebToken> Predicate<T> alternative(final Predicate<? super T>... predicates) {
525	        return new Predicate<T>() {
526	            @Override
527	            public boolean test(T t) {
528	                for (Predicate<? super T> predicate : predicates) {
529	                    try {
530	                        if (predicate.test(t)) {
531	                            return true;
532	                        }
533	
534	                        LOG.finer("[alternative] predicate failed: " + predicate);
535	                    } catch (VerificationException ex) {
536	                        LOG.log(Level.FINER, "[alternative] predicate " + predicate + " failed.", ex);
537	                    }
538	                }
539	
540	                return false;
541	            }
542	        };
543	    }
544	}
