2	
3	import java.security.SecureRandom;
4	import java.util.Base64;
5	import java.util.UUID;
6	import java.util.function.Supplier;
7	
8	public class SecretGenerator {
9	
10	    public static final int SECRET_LENGTH_256_BITS = 32;
11	    public static final int SECRET_LENGTH_384_BITS = 48;
12	    public static final int SECRET_LENGTH_512_BITS = 64;
13	    /**
14	     * Session ID length in bytes.
15	     * <p />
16	     * Both NIST and ANSSI ask for at least 128 bits of entropy, see <a href="https://github.com/keycloak/keycloak/issues/38663">#38663</a>.
17	     * As we are about to filter those session IDs on each node to find a key of the local segment using org.keycloak.models.sessions.infinispan.SessionAffinityService,
18	     * we add some more entropy so that the filtering then leaves enough entropy for those IDs.
19	     * Usually there are 256 segments in a cache. Just in case someone increases it, we add 16 bits.
20	     * This should handle the case when a caller connects to one node and generates codes (as it is the case with a keep-alive HTTP connection),
21	     * instead of a caller connecting to a random node on each request.
22	     */
23	    private static final int SESSION_ID_BYTES = 18;
24	    public static final Supplier<String> SECURE_ID_GENERATOR = () -> getInstance().generateBase64SecureId(SESSION_ID_BYTES);
25	
26	    public static final char[] UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".toCharArray();
27	
28	    public static final char[] DIGITS = "0123456789".toCharArray();
29	
30	    public static final char[] ALPHANUM = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789".toCharArray();
31	
32	    private static final SecretGenerator instance = new SecretGenerator();
33	
34	    private static final SecureRandom SECURE_RANDOM = new SecureRandom();
35	
36	    private SecretGenerator() {
37	    }
38	
39	    public static SecretGenerator getInstance() {
40	        return instance;
41	    }
42	    
43	    public String generateSecureID() {
44	        return generateSecureUUID().toString();
45	    }
46	
47	    public String generateBase64SecureId(int nBytes) {
48	        assert nBytes > 0;
49	        byte[] data = new byte[nBytes];
50	        SECURE_RANDOM.nextBytes(data);
51	        String id = Base64.getUrlEncoder().encodeToString(data);
52	
53	        // disallow a dot, as a dot is used as a separator in AuthenticationSessionManager.decodeBase64AndValidateSignature
54	        assert !id.contains(".");
55	
56	        // disallow a space, as session_state must not contain a space (see https://openid.net/specs/openid-connect-session-1_0.html#CreatingUpdatingSessions)
57	        assert !id.contains(" ");
58	
59	        return id;
60	    }
61	
62	    public static int nextInt(int bound) {
63	        return SECURE_RANDOM.nextInt(bound);
64	    }
65	
66	    public String randomString() {
67	        return randomString(SECRET_LENGTH_256_BITS, ALPHANUM);
68	    }
69	
70	    public String randomString(int length) {
71	        return randomString(length, ALPHANUM);
72	    }
73	
74	    public String randomString(int length, char[] symbols) {
75	        if (length < 1) {
76	            throw new IllegalArgumentException();
77	        }
78	        if (symbols == null || symbols.length < 2) {
79	            throw new IllegalArgumentException();
80	        }
81	
82	        char[] buf = new char[length];
83	
84	        for (int idx = 0; idx < buf.length; ++idx) {
85	            buf[idx] = symbols[SECURE_RANDOM.nextInt(symbols.length)];
86	        }
87	
88	        return new String(buf);
89	    }
90	
91	    public byte[] randomBytes() {
92	        return randomBytes(SECRET_LENGTH_256_BITS);
93	    }
94	
95	    public byte[] randomBytes(int length) {
96	        if (length < 1) {
97	            throw new IllegalArgumentException();
98	        }
99	
100	        byte[] buf = new byte[length];
101	        SECURE_RANDOM.nextBytes(buf);
102	        return buf;
103	    }
104	
105	    public String randomBytesHex(int length) {
106	        final StringBuilder sb = new StringBuilder();
107	        for (byte b : randomBytes(length)) {
108	            sb.append(Character.forDigit((b >> 4) & 0xF, 16));
109	            sb.append(Character.forDigit((b & 0xF), 16));
110	        }
111	        return sb.toString();
112	    }
113	
114	    /**
115	     * Returns the equivalent length for a destination alphabet to have the same
116	     * entropy bits than a byte array random generated.
117	     *
118	     * @param byteLengthEntropy The desired entropy in bytes
119	     * @param dstAlphabetLeng The length of the destination alphabet
120	     * @return The equivalent length in destination alphabet to have the same entropy bits
121	     */
122	    public static int equivalentEntropySize(int byteLengthEntropy, int dstAlphabetLeng) {
123	        return equivalentEntropySize(byteLengthEntropy, 256, dstAlphabetLeng);
124	    }
125	
126	    /**
127	     * Returns the equivalent length for a destination alphabet to have the same
128	     * entropy bits than another source alphabet.
129	     *
130	     * @param length The length of the string encoded in source alphabet
131	     * @param srcAlphabetLength The length of the source alphabet
132	     * @param dstAlphabetLeng The length of the destination alphabet
133	     * @return The equivalent length (same entropy) in destination alphabet for a string of length in source alphabet
134	     */
135	    public static int equivalentEntropySize(int length, int srcAlphabetLength, int dstAlphabetLeng) {
136	        return (int) Math.ceil(length * ((Math.log(srcAlphabetLength)) / (Math.log(dstAlphabetLeng))));
137	    }
138	
139	    /**
140	     * Returns a pseudo-UUID where all bits are random to have a maximum entropy.
141	     *
142	     * @return UUID with all bits random
143	     */
144	    public UUID generateSecureUUID() {
145	        byte[] data = randomBytes(16);
146	        return new UUID(toLong(data, 0), toLong(data, 8));
147	    }
148	
149	    private static long toLong(byte[] data, int offset) {
150	        return  ((data[offset] & 0xFFL) << 56) |
151	                ((data[offset + 1] & 0xFFL) << 48) |
152	                ((data[offset + 2] & 0xFFL) << 40) |
153	                ((data[offset + 3] & 0xFFL) << 32) |
154	                ((data[offset + 4] & 0xFFL) << 24) |
155	                ((data[offset + 5] & 0xFFL) << 16) |
156	                ((data[offset + 6] & 0xFFL) <<  8) |
157	                ((data[offset + 7] & 0xFFL)) ;
158	    }
159	}
