20	import java.util.Collections;
21	import java.util.Optional;
22	import java.util.Properties;
23	import java.util.Set;
24	
25	/**
26	 * <p>An utility class to resolve the value of a key based on the environment variables
27	 * and system properties available at runtime. In most cases, you do not want to resolve whatever system variable is available at runtime but specify which ones
28	 * can be used when resolving placeholders.
29	 *
30	 * <p>To resolve to an environment variable, the key must have a format like {@code env.<key>} where {@code key} is the name of an environment variable.
31	 * For system properties, there is no specific format and the value is resolved from a system property that matches the key.
32	 *
33	 * @author <a href="mailto:sthorger@redhat.com">Stian Thorgersen</a>
34	 */
35	public class SystemEnvProperties extends Properties {
36	
37	    /**
38	     * <p>An variation of {@link SystemEnvProperties} that gives unrestricted access to any system variable available at runtime.
39	     * Most of the time you don't want to use this class but favor creating a {@link SystemEnvProperties} instance that
40	     * filters which system variables should be available at runtime.
41	     */
42	    public static final SystemEnvProperties UNFILTERED = new SystemEnvProperties(Collections.emptySet()) {
43	        @Override
44	        protected boolean isAllowed(String key) {
45	            return true;
46	        }
47	    };
48	
49	    private final Set<String> allowedSystemVariables;
50	
51	    /**
52	     * Creates a new instance where system variables where only specific keys can be resolved from system variables.
53	     *
54	     * @param allowedSystemVariables the keys of system variables that should be available at runtime
55	     */
56	    public SystemEnvProperties(Set<String> allowedSystemVariables) {
57	        this.allowedSystemVariables = Optional.ofNullable(allowedSystemVariables).orElse(Collections.emptySet());
58	    }
59	
60	    @Override
61	    public String getProperty(String key) {
62	        if (key.startsWith("env.")) {
63	            String envKey = key.substring(4);
64	            return isAllowed(envKey) ? System.getenv().get(envKey) : null;
65	        } else {
66	            return isAllowed(key) ? System.getProperty(key) : null;
67	        }
68	    }
69	
70	    @Override
71	    public String getProperty(String key, String defaultValue) {
72	        String value = getProperty(key);
73	        return value != null ? value : defaultValue;
74	    }
75	
76	    protected boolean isAllowed(String key) {
77	        return allowedSystemVariables.contains(key);
78	    }
79	}
