509	   protected static String encodeFromArray(String segment, String[] encodingMap, boolean encodePercent)
510	   {
511	      StringBuilder result = new StringBuilder();
512	      for (int i = 0; i < segment.length(); i++)
513	      {
514	    	 char currentChar = segment.charAt(i);
515	         if (!encodePercent && currentChar == '%')
516	         {
517	            result.append(currentChar);
518	            continue;
519	         }
520	         String encoding = encode(currentChar, encodingMap);
521	         if (encoding == null)
522	         {
523	            result.append(currentChar);
524	         }
525	         else
526	         {
527	            result.append(encoding);
528	         }
529	      }
530	      return result.toString();
531	   }
