            case '-':
            case '.':
            case '_':
            case '~':
            case '!':
            case '$':
            case '&':
            case '\'':
            case '(':
            case ')':
            case '*':
            case '+':
            case ',':
            case ';':
            case '=':
            case ':':
               continue;
            case ' ':
               userInfoStringEncoding[i] = "%20";
               continue;
         }
         userInfoStringEncoding[i] = URLEncoder.encode(String.valueOf((char) i), StandardCharsets.UTF_8);
      }
   }

